/* =========================================================
   概算を出してよいかの判定(2026-08-31 社長判断)
   SLOTHの価格表は有効期限が 2026-10-05〜2027-01末。発効前の価格で概算を出さないため、
   その日まではSLOTHの品番(頭がCJ/ST/DF)をまとめて「個別見積り」に倒す。
   ★ b.quote を直接見ないこと。必ず QS_isQuoteOnly() を通す。
     サイト側の単一の情報源 functions/api/_bodies.js の isQuoteOnly() と同じ判定にしてある。
   ========================================================= */
window.QS_SLOTH_EFFECTIVE_FROM = '2026-10-05';

/** SLOTHカタログ(COLLECTIVE J+・SLOTH・D-FACTORY)の品番か */
window.QS_isSlothSku = function (sku) {
  return /^(CJ|ST|DF)\d/.test(String(sku == null ? '' : sku));
};

/** 今日(ブラウザのローカル日付・YYYY-MM-DD) */
window.QS_today = function () {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};

/** 概算を出さず個別見積りに倒す品番か */
window.QS_isQuoteOnly = function (body, today) {
  if (!body) return false;
  if (body.quote) return true;
  return window.QS_isSlothSku(body.sku) && (today || window.QS_today()) < window.QS_SLOTH_EFFECTIVE_FROM;
};

/** 個別見積りの理由 'material' / 'open-price' / 'not-effective-yet' */
window.QS_quoteOnlyReason = function (body, today) {
  if (!body) return null;
  if (body.quote) return body.quoteReason || 'material';
  return window.QS_isSlothSku(body.sku) && (today || window.QS_today()) < window.QS_SLOTH_EFFECTIVE_FROM
    ? 'not-effective-yet'
    : null;
};
